import 'package:alhambra_core/alhambra_core.dart';
import 'artifact_metadata.dart';
import 'artifact_type.dart';

/// A first-class output generated by intelligence workflows.
///
/// Data must be JSON-compatible or primitive to ensure generic cross-platform
/// serializability and presentation by renderers (A2UI, Flutter, Web).
final class IntelligenceArtifact {
  final ArtifactId id;
  final ArtifactType type;
  final String title;
  final String? description;
  final Object? data;
  final List<EvidenceId> evidenceIds;
  final ArtifactMetadata metadata;

  const IntelligenceArtifact({
    required this.id,
    required this.type,
    required this.title,
    this.description,
    this.data,
    this.evidenceIds = const [],
    required this.metadata,
  });

  @override
  String toString() =>
      'IntelligenceArtifact($id: "$title" [${type.name}], evidence: ${evidenceIds.length})';
}
